'use client';

// An AI action's panel (docs/specs/026-plan/automations.md "AI actions"): Summarise Card's place (a comment, or one of
// the plan's text fields), Suggest Card Type's choice (set it, or comment the suggestion) and Triage's parts (the
// priority, the labels or both). Under each, the line saying it uses AI and what that counts toward, and that its
// writes are marked Generated by AI.

import {
  AUTOMATION_AI_LABELS_MAX,
  AUTOMATION_AI_PER_DAY,
  AUTOMATION_AI_SUMMARY_MAX,
  type AutomationAi,
} from '@liveplanner/items';
import type { ReactNode } from 'react';
import { SparkleIcon } from '@liveplanner/ui';
import { outlineFields, type AutomationOutline } from '../automation-outline';
import { ChipToggles, PanelField, PanelSelect } from './panel-parts';

const COMMENT = '';

/** The plan's text fields a summary may go in: its custom Text and Long Text fields. */
export function summaryFields(outline: Pick<AutomationOutline, 'types'>) {
  const text = new Set(
    outline.types.flatMap((t) =>
      (t.custom ?? []).filter((c) => c.kind === 'text' || c.kind === 'longtext').map((c) => c.id),
    ),
  );
  return outlineFields(outline.types).filter((f) => text.has(f.id));
}

/** "Uses AI": what the step counts toward, and how its writes are marked. */
/** A note about AI, with the sparkle: the AI steps' cost line, Describe a Rule's, the drafted rule's. */
export function AiNote({ children, id }: { children: ReactNode; id?: string }) {
  return (
    <p
      id={id}
      className="flex items-start gap-2 rounded-lg bg-brand-50 px-3 py-2.5 text-[13px] text-brand-900 dark:bg-brand-500/15 dark:text-brand-100"
    >
      <SparkleIcon size={14} aria-hidden className="mt-0.5 shrink-0" />
      <span>{children}</span>
    </p>
  );
}

export function AiCostNote() {
  return (
    <AiNote>
      Uses AI: counts toward this plan&rsquo;s {AUTOMATION_AI_PER_DAY} AI steps a day. What it
      writes is by Automation and marked Generated by AI. Test on a Card says what it would do
      without asking.
    </AiNote>
  );
}

export function AiStepPanel({
  step,
  outline,
  onChange,
}: {
  step: AutomationAi;
  outline: AutomationOutline;
  onChange: (next: AutomationAi) => void;
}) {
  return (
    <div className="flex flex-col gap-4">
      {step.task === 'summarise' ? (
        <SummarisePart step={step} outline={outline} onChange={onChange} />
      ) : step.task === 'card_type' ? (
        <PanelField
          label="With the Suggestion"
          hint="It picks only from this plan's card types, by the card's title, description and checklist."
        >
          {(id) => (
            <PanelSelect
              id={id}
              value={step.set ? 'set' : 'comment'}
              onChange={(e) => onChange({ ...step, set: e.target.value === 'set' })}
            >
              <option value="set">Set the Card Type</option>
              <option value="comment">Comment the Suggestion</option>
            </PanelSelect>
          )}
        </PanelField>
      ) : (
        <ChipToggles
          label="What It Sets"
          options={[
            { value: 'priority', label: 'Priority' },
            { value: 'labels', label: `Up to ${AUTOMATION_AI_LABELS_MAX} Labels` },
          ]}
          value={[...(step.priority ? ['priority'] : []), ...(step.labels ? ['labels'] : [])]}
          // At least one stays picked.
          onChange={(next) => {
            const priority = next.includes('priority');
            const labels = next.includes('labels');
            if (priority || labels) onChange({ ...step, priority, labels });
          }}
        />
      )}
      {step.task === 'triage' && step.labels ? (
        <p className="-mt-2 text-[12px] text-slate-500 dark:text-slate-400">
          Labels come only from those this plan&rsquo;s cards already use.
        </p>
      ) : null}
      <AiCostNote />
    </div>
  );
}

function SummarisePart({
  step,
  outline,
  onChange,
}: {
  step: Extract<AutomationAi, { task: 'summarise' }>;
  outline: AutomationOutline;
  onChange: (next: AutomationAi) => void;
}) {
  const fields = summaryFields(outline);
  // A field the plan no longer has stays listed, so the panel shows what the rule holds.
  const gone = step.field && !fields.some((f) => f.id === step.field) ? step.field : null;
  return (
    <PanelField
      label="Where It Goes"
      hint={`At most ${AUTOMATION_AI_SUMMARY_MAX} characters of plain text, from the card's title, description, checklist and latest comments.`}
    >
      {(id) => (
        <PanelSelect
          id={id}
          value={step.field ?? COMMENT}
          onChange={(e) =>
            onChange(
              e.target.value === COMMENT
                ? { kind: 'ai', task: 'summarise' }
                : { kind: 'ai', task: 'summarise', field: e.target.value },
            )
          }
        >
          <option value={COMMENT}>A Comment</option>
          {fields.map((f) => (
            <option key={f.id} value={f.id}>
              {f.name}
            </option>
          ))}
          {gone ? <option value={gone}>A field no longer here</option> : null}
        </PanelSelect>
      )}
    </PanelField>
  );
}
